int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int rc;
	int i;

	if (d->msg[0] < 0x20 || d->msg[0] > 0x2f)
		return -EINVAL;

	if (d->msg[1] < 0x01 || d->msg[1] > 0x0f)
		return -EINVAL;

	d->msg[4] = 0x10;
	d->msg[5] = 0x00;
	d->msg[6] = 0x00;
	d->msg[7] = 0x00;
	d->msg[8] = 0x00;
	d->msg[9] = 0x00;

	for (i = 0; i < 3; i++) {
		rc = dvb_frontend_set_tone(fe, DVB_FRONTEND_TONE_OFF);
		if (rc)
			return rc;
		rc = dvb_frontend_set_voltage(fe, SEC_VOLTAGE_13);
		if (rc)
			return rc;
		msleep(100);
		rc = dvb_frontend_set_tone(fe, DVB_FRONTEND_TONE_ON);
		if (rc)
			return rc;
		rc = dvb_frontend_set_voltage(fe, SEC_VOLTAGE_18);
		if (rc)
			return rc;
		msleep(100);
		rc = dvb_frontend_set_tone(fe, DVB_FRONTEND_TONE_OFF);
		if (rc)
			return rc;
		rc = dvb_frontend_set_voltage(fe, SEC_VOLTAGE_13);
		if (rc)
			return rc;
		msleep(100);
		rc = dvb_frontend_send_diseqc_msg(fe, d->msg, 10);
		if (rc)
			return rc;
		msleep(200);
		if (rc >= 0)
			return 0;
	}

	return rc;
}

int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i;
	struct dvb_diseqc_dev *diseqc = fe->diseqc;

	/* Validate message length */
	if (d->msg[0] < 1 || d->msg[0] > 6) {
		dprintk(1, "diseqc: invalid message length %d\n", d->msg[0]);
		return -EINVAL;
	}

	d->msg[0] = ((d->msg[0] - 1) << 2) | (d->msg[0] & 0x03);
	d->msg[1] = 0x30;

	if (fe->ops.set_tone)
		fe->ops.set_tone(fe, SEC_TONE_OFF);

	if (fe->ops.set_voltage)
		fe->ops.set_voltage(fe, SEC_VOLTAGE_13);

	msleep(150);

	for (i = 0; i < 50; i++) {
		if (fe->ops.diseqc_master_cmd)
			break;
		msleep(10);
	}

	if (i == 50) {
		dprintk(1, "diseqc: timeout waiting for LNB to be ready\n");
		return -ETIMEDOUT;
	}

	if (fe->ops.diseqc_master_cmd(fe, d) < 0)
		return -EIO;

	for (i = 0; i < 50; i++) {
		if (fe->ops.diseqc_rcv_slave_reply)
			break;
		msleep(10);
	}

	if (i == 50) {
		dprintk(1, "diseqc: timeout waiting for reply\n");
		return -ETIMEDOUT;
	}

	if (fe->ops.diseqc_rcv_slave_reply(fe, d) < 0)
		return -EIO;

	return 0;
}

int dvb_diseqc_send_master_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i, result = 0;

	if (d->msg[0] < 4 || d->msg[0] > 6) {
		dprintk(1, "invalid DiSEqC message length (0x%02x)\n", d->msg[0]);
		return -EINVAL;
	}

	if (d->msg[1] & 0x01) {
		d->msg[1] &= ~0x01;
		d->msg[1] |= (d->msg[0] & 0x03);
	}

	d->msg[1] |= (d->msg[0] & 0x03);

	if (d->msg[0] > 6)
		d->msg[0] = 6;

	for (i = 0; i < d->msg[0]; i++)
		d->msg[i] &= 0x7f;

	d->msg[0]--;

	if (d->msg[0] < 3) {
		d->msg[0] = 3;
		d->msg[1] |= 0x04;
	}

	if (d->msg[1] & 0x01)
		d->msg[1] |= 0x01;

	if (fe->ops.diseqc_send_master_cmd) {
		result = fe->ops.diseqc_send_master_cmd(fe, d);
		if (result < 0)
			return result;
	}

	return result;
}

int dvb_frontend_send_diseqc_msg(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int i;
	int rc = 0;

	if (d->msg[0] > 6) {
		rc = -EINVAL;
		goto error;
	}

	if (dvb_debug) {
		printk(KERN_DEBUG "DiSEqC: sending master command\n");
		for (i = 0; i < d->msg[0] + 1; i++)
			printk(KERN_DEBUG "byte %d: 0x%02x\n", i, d->msg[i]);
	}

	d->msg[0]++;
	d->msg[1] &= 0x0f;

	if (d->msg[1] & 0x08)
		d->msg[1] = (d->msg[1] & ~0x08) | 0x10;

	d->msg[1] &= 0x1f;

	d->msg[1] |= 0x20;

	d->msg[1] |= 0x80;

	d->msg[0] = 6;

	for (i = 0; i < 100; i++) {
		if (fe->ops->set_tone && fe->ops->set_voltage)
			break;
		udelay(10);
	}

	udelay(1000);

	rc = fe->ops->send_diseqc_master_cmd(fe, d);

	udelay(1000);

	return rc;

error:
	return rc;
}

int dvb_diseqc_send_master_cmd(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d)
{
	int rc;

	if (d->msg_len < 1 || d->msg_len > 6) {
		dvb_frontend_log_error(fe, "DiSEqC message length invalid: %d", d->msg_len);
		return -EINVAL;
	}

	if (dvb_frontend_debug)
		dvb_frontend_log_debug(fe, "DiSEqC master cmd: %*ph", d->msg_len, d->msg);

	d->cmd_len = d->msg_len;
	d->tx_toneBURST = DISEQC_BURST_A;

	rc = dvb_frontend_wait_for_lnb(fe);
	if (rc)
		return rc;

	msleep(20);

	rc = dvb_frontend_exec_cmd(fe, d);
	if (rc)
		return rc;

	if (d->tx_toneBURST == DISEQC_BURST_A)
		msleep(50);
	else if (d->tx_toneBURST == DISEQC_BURST_T)
		msleep(100);

	return 0;
}
